WITH SessionSummary AS (SELECT session_id, SUM(CASE WHEN event_type = 'add_to_cart' THEN duration_sec ELSE 0 END) AS add_to_cart_duration_sec, ROUND((100 * SUM(CASE WHEN event_type = 'click' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_click FROM web_events GROUP BY session_id) SELECT s.customer_id, S.add_to_cart_duration_sec, S.pct_click FROM sessions s LEFT JOIN SessionSummary S ON s.id = S.session_id WHERE S.pct_click >= 49 ORDER BY add_to_cart_duration_sec;
